package java.util;
import java.util.function.*;
public final class OptionalInt {private static final OptionalInt EMPTY=new OptionalInt();private final boolean present;private final int value;private OptionalInt(){present=false;value=0;}private OptionalInt(int v){present=true;value=v;}public static OptionalInt empty(){return EMPTY;}public static OptionalInt of(int v){return new OptionalInt(v);}public int getAsInt(){if(!present)throw new NoSuchElementException("No value present");return value;}public boolean isPresent(){return present;}public void ifPresent(IntConsumer c){if(present)c.accept(value);}public int orElse(int other){return present?value:other;}public int orElseGet(IntSupplier s){return present?value:s.getAsInt();}public <X extends Throwable> int orElseThrow(Supplier<? extends X> s) throws X{if(present)return value;throw s.get();}public boolean equals(Object o){if(!(o instanceof OptionalInt))return false;OptionalInt x=(OptionalInt)o;return present==x.present&&(!present||value==x.value);}public int hashCode(){return present?Integer.hashCode(value):0;}public String toString(){return present?"OptionalInt["+value+"]":"OptionalInt.empty";}}
